<?php
declare(strict_types=1);
namespace Tests;
#[\PHPUnit\Framework\Attributes\Group('s3-integration')]
final class S3IntegrationTest extends TestCase
{
    public function testPrivateRealS3RoundTripAndFailureLeavesNoMetadata():void
    {
        $path=getenv('ELANG_TEST_S3_CONFIG');if(!$path) self::markTestSkipped('Set ELANG_TEST_S3_CONFIG to an isolated local S3 credential fixture.');$document=json_decode(file_get_contents($path),true,16,JSON_THROW_ON_ERROR);$credential=$document['identities'][0]['credentials'][0];$endpoint=getenv('ELANG_TEST_S3_ENDPOINT')?:'http://127.0.0.1:18333';self::assertMatchesRegularExpression('~^http://(127\.0\.0\.1|seaweed):[0-9]+$~',$endpoint,'This test must never target an external bucket.');$bucket='elang-test-'.bin2hex(random_bytes(6));$options=['version'=>'latest','region'=>'us-east-1','endpoint'=>$endpoint,'use_path_style_endpoint'=>true,'credentials'=>['key'=>$credential['accessKey'],'secret'=>$credential['secretKey']],'http'=>['connect_timeout'=>2,'timeout'=>5],'retries'=>0];$s3=new \Aws\S3\S3Client($options);$s3->createBucket(['Bucket'=>$bucket]);
        try {
            $app=$this->application(['key'=>base64_encode(random_bytes(32)),'files'=>['disk'=>'s3','s3'=>['bucket'=>$bucket,'region'=>'us-east-1','endpoint'=>$endpoint,'path_style'=>true,'key'=>$credential['accessKey'],'secret'=>$credential['secretKey']]]]);$db=$app->container->get(\Elang\Database\Database::class)->connection();\Elang\Auth\Schema::up($db);\Elang\Storage\Schema::up($db);$user=$app->container->get(\Elang\Auth\Users::class)->create('S3 QA','s3@example.test','A unique account passphrase','user',true);$files=$app->container->get(\Elang\Storage\Files::class);$row=$files->put($user,'document.txt','Private S3 payload');$download=$files->download($user,$row['id']);self::assertSame('Private S3 payload',stream_get_contents($download['stream']));fclose($download['stream']);self::assertSame(hash('sha256','Private S3 payload'),$row['sha256']);$key=$db->fetchOne('SELECT object_key FROM elang_files');$anonymous=(new \GuzzleHttp\Client(['http_errors'=>false]))->get($endpoint.'/'.$bucket.'/elang/'.$key);self::assertSame(403,$anonymous->getStatusCode());$files->delete($user,$row['id']);self::assertSame(0,(int)$db->fetchOne('SELECT COUNT(*) FROM elang_files'));
            $bad=$this->application(['key'=>base64_encode(random_bytes(32)),'files'=>['disk'=>'s3','s3'=>['bucket'=>$bucket,'region'=>'us-east-1','endpoint'=>$endpoint,'path_style'=>true,'key'=>'invalid-qa-key','secret'=>'invalid-qa-secret']]]);$otherDb=$bad->container->get(\Elang\Database\Database::class)->connection();\Elang\Auth\Schema::up($otherDb);\Elang\Storage\Schema::up($otherDb);$other=$bad->container->get(\Elang\Auth\Users::class)->create('Other','other@example.test','A unique account passphrase','user',true);try { $bad->container->get(\Elang\Storage\Files::class)->put($other,'x.txt','denied');self::fail('Invalid S3 credentials were accepted.'); }catch(\League\Flysystem\UnableToWriteFile) {}self::assertSame(0,(int)$otherDb->fetchOne('SELECT COUNT(*) FROM elang_files'));
        }finally { foreach(($s3->listObjectsV2(['Bucket'=>$bucket])['Contents']??[]) as $object) $s3->deleteObject(['Bucket'=>$bucket,'Key'=>$object['Key']]);$s3->deleteBucket(['Bucket'=>$bucket]); }
    }
}
